function i(t,n={}){return t?new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",...n}).format(new Date(t)):"—"}function o(t){if(!t)return"—";const n=Date.now()-new Date(t).getTime(),r=Math.floor(n/6e4);if(r<1)return"just now";if(r<60)return`${r}m ago`;const e=Math.floor(r/60);return e<24?`${e}h ago`:`${Math.floor(e/24)}d ago`}function a(t=""){return t.split(" ").map(n=>n[0]).join("").toUpperCase().slice(0,2)}export{i as f,a as i,o as t};
